manifest<-list();legends<-character()
save<-function(id,p,h,data,legend,w=174){
 for(k in c('title','subtitle','caption'))if(is.character(p$labels[[k]]))p$labels[[k]]<-paste(strwrap(p$labels[[k]],width=floor(w/if(k=='title')1.7 else if(k=='subtitle')1.4 else 1.35)),collapse='\n')
 f<-file.path(out,'figures',paste0(id,'.pdf'));im<-file.path(out,'review',paste0(id,'.png'));tb<-file.path(out,'tables',paste0(id,'.csv'))
 fwrite(data,tb);cairo_pdf(f,width=w/25.4,height=h/25.4,family='Arial');print(p);dev.off()
 ragg::agg_png(im,width=w,height=h,units='mm',res=450,background='white');print(p);dev.off()
 manifest[[id]]<<-data.table(ID=id,Group='更新与补充分析',PDF=f,PNG=im,Table=tb,WidthMM=w,HeightMM=h,Mode='Updated/new',Rows=nrow(data))
 legends<<-c(legends,paste0('## ',id,'\n\n',legend,'\n'));message(id)
}
oldm<-fread(file.path(old,'figure_manifest.csv'))
for(i in seq_len(nrow(oldm))){a<-oldm[i];if(a$ID%chin%c('13_cell_line_projections','14_PRISM_candidate_observations','16_PRISM_shared_drug_measurements'))next
 for(k in c('PDF','PNG','Table')){dest<-file.path(out,switch(k,PDF='figures',PNG='review',Table='tables'),basename(a[[k]]));stopifnot(file.copy(a[[k]],dest,overwrite=TRUE));set(a,j=k,value=dest)}
 a[,Mode:='Byte-identical reuse from v13'];manifest[[a$ID]]<-a
}
