p<-ggplot(a,aes(Class,Label,fill=Probability))+geom_tile(color='white',linewidth=.4)+geom_text(aes(label=sprintf('%.2f',Probability)),size=8/ggplot2::.pt)+scale_fill_gradient(low='white',high='#8DAFBD',limits=c(0,1),name='Probability')+labs(title='Current 114-gene cell-line projections',subtitle='28 lines | 114 / 114 features | C1: 3, C2: 10, C3: 15',x=NULL,y=NULL,caption='* Old PRISM AUC available. [changed]: label differs from the 123-gene model. Probabilities are not calibrated in cell lines.')
