cand[,Compound:=sub('_[0-9]+$','',Drug)];a<-unique(cand[,.(Compound,CellLineName,Prediction,ModelID,Assay,PRISMCompound,AUC,ObservationStatus)])
stopifnot(!anyDuplicated(a[,.(Compound,ModelID)]))
a[,Compound:=factor(Compound,levels=rev(sort(unique(Compound))))];a[,Line:=paste0(CellLineName,'\nprojected ',Prediction)];a[,Text:=fifelse(is.finite(AUC),sprintf('%.2f',AUC),fifelse(ObservationStatus=='No accepted assay identity','?','NA'))]
p<-ggplot(a,aes(Line,Compound,fill=AUC))+geom_tile(color='white',linewidth=.5)+geom_text(aes(label=Text),size=8/ggplot2::.pt)+scale_fill_gradient(low='#86AFC5',high='white',na.value='#E5E5E5',name='Observed AUC')+labs(title='Candidate PRISM measurements after identity repair',subtitle=sprintf('18 named compounds | %d observed assay-line values',sum(is.finite(a$AUC))),x=NULL,y=NULL,caption='NA: matched assay, no measurement. ?: no accepted identity link. Three lines only; HuH28 has uncertain subtype projection.')
save('14_PRISM_candidate_observations',p,143,a,'Original nine candidates plus prior comparators, 18 unique named compounds. Synonyms linked before looking at responses. Identical compounds with two GDSC model IDs are displayed once; their prediction models remain separate elsewhere. No salt or assay averaging. No subtype mean or efficacy test. Resource-name mappings are not an exhaustive structure audit.')
shared<-rd('PRISM_unique_shared_assay_cells');assays<-sort(unique(shared$Assay));amax<-max(shared$AUC,na.rm=TRUE);amin<-min(shared$AUC,na.rm=TRUE)
for(j in 1:2){keys<-assays[seq.int((j-1)*48+1,min(j*48,length(assays)))];a<-shared[Assay%chin%keys];a[,Line:=paste0(CellLineName,'\nprojected ',Prediction)];a[,Assay:=factor(Assay,levels=rev(keys))]
 labs<-setNames(sub(' \\(BRD:.*$','',keys),keys)
 dup<-duplicated(labs)|duplicated(labs,fromLast=TRUE);labs[dup]<-paste0(labs[dup],' [',seq_along(labs)[dup],']')
 p<-ggplot(a,aes(Line,Assay,fill=AUC))+geom_tile(color='white',linewidth=.25)+geom_text(aes(label=ifelse(is.finite(AUC),sprintf('%.2f',AUC),'NA')),size=7.5/ggplot2::.pt)+scale_y_discrete(labels=labs)+scale_fill_gradient(low='#86AFC5',high='white',na.value='#E5E5E5',limits=c(amin,amax),name='Observed AUC')+labs(title=paste('Shared PRISM assays',j,'/ 2'),subtitle='95 assay identities across 100 GDSC2 model IDs',x=NULL,y=NULL,caption='Every matched assay retained, including missing values. Duplicate assays remain separate; exact BRD IDs are in source data.')
 save(paste0('16',letters[j],'_PRISM_shared_drug_measurements'),p,229,a,'All 95 accepted shared assay IDs crossed with three lines, sorted alphabetically and split into two pages. Case/punctuation-normalized names and explicit resource/curated aliases. Held chemistry and rejected incorrect aliases excluded from accepted joins but retained in crosswalk tables. No cross-drug potency inference.')
}

