 save(sprintf('%02d_%s_candidate_study_intervals',27+j,st),p,213,a,'All 42 candidate-comparison-study cells per subtype, including non-estimable cells; estimates require at least two samples in both groups. Welch t intervals. No selection by significance; fixed global SD only changes display units.')
